-- S7: 12 nuevas y 2 revisiones. No juicio, promoción, puente, IG ni deprecaciones.
BEGIN;
DO $s7$
DECLARE p jsonb; q jsonb; e jsonb; cd text; ver int; n int:=0; b_leg jsonb; b_bridge jsonb; b_dep jsonb; b_pub jsonb; b_judge jsonb; b_cand int; lid int; t record;
BEGIN
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO b_leg FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_bridge FROM lf_ops.lf_nucleo_cobertura_legada r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO b_pub FROM lf_ops.nucleo_regla_versiones r WHERE estado='PUBLICADA';
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO b_judge FROM lf_ops.nucleo_juicios r;
 SELECT count(*) INTO b_cand FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND ((SELECT count(distinct legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>139 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='PUBLICADA')<>157 OR b_cand<>8) THEN RAISE EXCEPTION 'S7_BASELINE_DRIFT'; END IF;
