nte construya URL de proveedor o callback arbitrarios. Preparación exige checkout, quote y medio validados.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s7c12_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s7c12_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s7c12_violacion"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":false,"s7c12_contexto":false,"s7c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":false,"s7c12_contexto":false,"s7c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":false,"s7c12_contexto":true,"s7c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":false,"s7c12_contexto":true,"s7c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":true,"s7c12_contexto":false,"s7c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":true,"s7c12_contexto":false,"s7c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s7c12_intento":true,"s7c12_contexto":true,"s7c12_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s7c12_intento":true,"s7c12_contexto":true,"s7c12_violacion":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/540","solicitante":"Cristhian / Claude S7 2026-11-23"}},{"modo":"HEREDA","tipo":"REVISION","clase":"BACKEND","clave":"s5_session_expiry_abandoned","dueno":"TECNICO","codigo":"S5-C12","efecto":"BLOQUEAR","origen":{"ref":"lf_ops.reglas/14","tipo":"MIGRACION","solicitante":"Cristhian/Claude LF S5 2026-11-23"},"titulo":"Impedir extensión indebida de expiración de sesión OTP no verificada","alcance":"BACKEND","familia":"SESSION","impacto":"REVISAR","autoridad":"LEG-TECNICO","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s5c12_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s5c12_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s5c12_violacion"},"der":{"lit":true}}},"naturaleza":"CONDUCTA","descripcion":"Al establecer o modificar expiración de una sesión onboarding sin OTP verificado, BLOQUEAR extender lf_client.onboarding_sessions.expires_at más allá de la ventana AUTH/ONBOARDING_UNVERIFIED_SESSION_EXPIRATION_MINUTES de public.lf_global_config desde created_at mientras otp_verified_at sea nulo. Complementa M4-B01, que gobierna reanudación; registro de abandono queda residual sin estado persistido.","version_anterior":1,"hash_anterior":"9dfc2f15f9d4284117dc0bb35620b698bff2eed7ca034f3a6c3de5f507c82c46","motivo_revision":"Juicio independiente: no existe estado persistido; precisar expiración real sin inventarlo.","pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":false,"s5c12_contexto":false,"s5c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":false,"s5c12_contexto":false,"s5c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":false,"s5c12_contexto":true,"s5c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":false,"s5c12_contexto":true,"s5c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":true,"s5c12_contexto":false,"s5c12_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":true,"s5c12_contexto":false,"s5c12_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s5c12_intento":true,"s5c12_contexto":true,"s5c12_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s5c12_intento":true,"s5c12_contexto":true,"s5c12_violacion":true},"esperado":true}]},{"modo":"HEREDA","tipo":"REVISION","clase":"BACKEND","clave":"s6_reg_atq_012","dueno":"TECNICO","codigo":"S6-C03","efecto":"BLOQUEAR","origen":{"ref":"lf_ops.reglas/132","tipo":"MIGRACION","solicitante":"Cristhian/Claude S6 2026-11-23"},"titulo":"Persistir bloqueo de sesión al agotar último reenvío OTP","alcance":"BACKEND","familia":"SECURITY","impacto":"REVISAR","autoridad":"LEG-TECNICO","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s6c03_intento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s6c03_contexto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s6c03_violacion"},"der":{"lit":true}}},"naturaleza":"CONDUCTA","descripcion":"Al agotar intentos del último reenvío, conforme a AUTH/OTP_MAX_ATTEMPTS y AUTH/OTP_MAX_RESENDS de public.lf_global_config y lf_client.onboarding_sessions.otp_attempt_count_current y otp_resend_count, BLOQUEAR finalizar ese evento sin persistir blocked_at y exigir nuevo onboarding. Complementa S2-C02 (continuación) y S5-C13 (invalidación y cooldown); no repetir esos guards.","version_anterior":1,"hash_anterior":"d6f83f8ee727c896df36d30f40d9ea77b943701d9ae43006aa1664b0669dafe1","motivo_revision":"Juicio independiente: separar invalidación y cooldown de S5-C13; precisar bloqueo persistido y alcance de S2-C02.","pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":false,"s6c03_contexto":false,"s6c03_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":false,"s6c03_contexto":false,"s6c03_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":false,"s6c03_contexto":true,"s6c03_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":false,"s6c03_contexto":true,"s6c03_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":true,"s6c03_contexto":false,"s6c03_violacion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":true,"s6c03_contexto":false,"s6c03_violacion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s6c03_intento":true,"s6c03_contexto":true,"s6c03_violacion":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s6c03_intento":true,"s6c03_contexto":true,"s6c03_violacion":true},"esperado":true}]}]$packets$::jsonb) LOOP
  cd:=p->>'codigo'; ver:=CASE WHEN p->>'tipo'='REVISION' THEN 2 ELSE 1 END;
  lid:=substring(p->'origen'->>'ref' from '[0-9]+$')::int;
  IF (SELECT count(*) FROM lf_ops.reglas)=586 AND NOT EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN RAISE EXCEPTION 'S7_LEGACY_MISSING %',lid; END IF;
  IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S7_ALREADY_COVERED %',lid; END IF;
  IF ver=2 THEN
   IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash_anterior') THEN RAISE EXCEPTION 'S7_REVISION_HASH_DRIFT %',cd; END IF;
   q:=lf_ops.nucleo_regla_proponer_v1(p||jsonb_build_object('hash_anterior',repeat('0',64)),false);
   IF q->>'resultado'<>'RECHAZADA' OR (q->>'bloqueantes')::int<1 THEN RAISE EXCEPTION 'S7_NEGATIVE_HASH_ACCEPTED %',cd; END IF;
  END IF;
  q:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S7_PREFLIGHT_FAIL % %',cd,q; END IF;
  q:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>ver THEN RAISE EXCEPTION 'S7_CREATE_FAIL % %',cd,q; END IF;
  IF ver=2 AND (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'DESCARTADA' THEN RAISE EXCEPTION 'S7_OLD_VERSION_NOT_ARCHIVED %',cd; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=ver)<>8 OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=ver)<>8 THEN RAISE EXCEPTION 'S7_VECTOR_INVALID %',cd; END IF;
  e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL OR (e->>'version')::int<>ver THEN RAISE EXCEPTION 'S7_GATE_FAIL % %',cd,e; END IF;
  n:=n+1;
  RAISE NOTICE 'S7_CANDIDATE % v% hash=%',cd,ver,e->>'hash_paquete';
 END LOOP;
 IF n<>14 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+12
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM b_leg
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada r) IS DISTINCT FROM b_bridge
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM b_dep
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones r WHERE estado='PUBLICADA') IS DISTINCT FROM b_pub
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.nucleo_juicios r) IS DISTINCT FROM b_judge
 THEN RAISE EXCEPTION 'S7_CONSERVATION_FAIL'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.pantallas WHERE id=36) AND jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S7_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S7_PASS 12 NUEVAS 2 REVISIONES 112 VECTORES 0 PROMOCIONES';
END $s7$;
COMMIT;
